"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[85],{1442:(e,a,o)=>{o.d(a,{cn:()=>i});function i(...e){return e.filter(Boolean).join(" ")}},2381:(e,a,o)=>{o.d(a,{kL:()=>n,mc:()=>i});let i=[{slug:"astronomia",n:"01",school:"Cielo y Medida",title:"Astronom\xeda",degree:"Licenciado/a en Astronom\xeda",years:5,jornada:"Nocturna",cupos:24,arancel:598e4,image:"/images/observatorio.jpg",alt:"C\xfapula del observatorio bajo la V\xeda L\xe1ctea, en una ladera del norte de Chile",lead:"Cinco a\xf1os para medir el cielo del sur. El dato se toma de noche. El paper, de d\xeda.",body:"Chile tiene el cielo m\xe1s limpio del planeta y lo ense\xf1a, a menudo, como postal. En NOCTUA la astronom\xeda es oficio: \xf3ptica, reducci\xf3n, serie, escritura. El primer a\xf1o no hay software de cat\xe1logo. Hay c\xfapula, bit\xe1cora y un cerro que se sube. La estaci\xf3n de Atacama es una residencia, no un viaje de turismo.",forWhom:"Quien quiere el instrumento, no el afiche de la NASA. Quien acepta el fr\xedo, la hora y que una noche nublada tambi\xe9n se anota.",plan:[{year:"1–2",items:"F\xedsica, c\xe1lculo, \xf3ptica, programaci\xf3n cient\xedfica, bit\xe1cora del cerro."},{year:"3–4",items:"Astrof\xedsica, reducci\xf3n, series, estaci\xf3n Atacama, seminario de doce."},{year:"5",items:"Memoria: una serie propia, un modelo, una defensa p\xfablica."}],weights:[{label:"NEM",value:"15%"},{label:"Ranking",value:"15%"},{label:"Comp. Lectora",value:"15%"},{label:"Comp. Matem\xe1tica 1",value:"35%"},{label:"Ciencias",value:"20%"}],faculty:"tomas-henriquez",portfolio:!1,vigilia:!0,outcomes:["Observatorios y estaciones","Investigaci\xf3n y reducci\xf3n","Instrumentaci\xf3n y dato"]},{slug:"datos",n:"02",school:"Cielo y Medida",title:"Ingenier\xeda en Datos y Observaci\xf3n",degree:"Ingeniero/a en Datos y Observaci\xf3n",years:6,jornada:"Nocturna",cupos:36,arancel:632e4,image:"/images/pasillo.jpg",alt:"Pasillo de hormig\xf3n del campus de noche, una l\xe1mpara \xe1mbar al fondo",lead:"Sistemas que se pueden auditar. Modelos que declaran su sesgo. El laboratorio abre cuando la ciudad genera su ruido.",body:"No formamos ‘el talento del futuro’. Formamos gente que escribe c\xf3digo que se puede leer y series que se pueden defender. Seis a\xf1os, matem\xe1tica seria, talleres de doce. El \xfaltimo a\xf1o es un sistema en producci\xf3n — un observatorio, un hospital, un municipio — no un demo.",forWhom:"Quien quiere rigor, no bootcamp. Quien acepta que el primer a\xf1o es matem\xe1tica y que el software se defiende como se defiende un teorema.",plan:[{year:"1–2",items:"C\xe1lculo, \xe1lgebra, estructuras de datos, sistemas, \xe9tica del dato."},{year:"3–4",items:"Series, redes, aprendizaje de m\xe1quinas, taller de observaci\xf3n."},{year:"5–6",items:"T\xedtulo: un sistema en uso, con bit\xe1cora y defensa."}],weights:[{label:"NEM",value:"15%"},{label:"Ranking",value:"15%"},{label:"Comp. Lectora",value:"15%"},{label:"Comp. Matem\xe1tica 1",value:"35%"},{label:"Ciencias",value:"20%"}],faculty:"tomas-henriquez",portfolio:!1,vigilia:!1,outcomes:["Infraestructura y series","Investigaci\xf3n aplicada","Producto con responsabilidad de dato"]},{slug:"cine",n:"03",school:"Cielo y Medida",title:"Cine",degree:"Licenciado/a en Cine",years:4,jornada:"Nocturna",cupos:24,arancel:512e4,image:"/images/cine.jpg",alt:"Sala oscura del instituto: butacas vac\xedas y un haz de proyector",lead:"La luz se ense\xf1a cuando falta. Cuatro a\xf1os de toma, montaje y una pieza que se proyecta.",body:"El cine en NOCTUA no es un moodboard ni una industria de pitch. Se ense\xf1a la noche como material: exposici\xf3n, silencio, el grano, la ciudad encendida. El primer a\xf1o se filma en pel\xedcula y se revela. El egreso es una pieza de veintid\xf3s minutos, proyectada en la sala oscura, no un link.",forWhom:"Quien quiere el oficio de la toma, no el de la red. Quien acepta que una noche de rodaje no se recupera con un filtro.",plan:[{year:"1–2",items:"Fotograf\xeda, sonido, montaje, historia del cine chileno y del Pac\xedfico."},{year:"3",items:"Taller de noche urbana, documental, ficci\xf3n breve. Encargo."},{year:"4",items:"T\xedtulo: una pieza proyectada, con ficha y defensa."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"35%"},{label:"Comp. Matem\xe1tica 1",value:"10%"},{label:"Historia y Cs. Sociales",value:"15%"}],faculty:"francisca-valdivia",portfolio:!0,vigilia:!0,outcomes:["Direcci\xf3n y fotograf\xeda","Montaje y archivo audiovisual","Documental de ciudad"]},{slug:"sueno",n:"04",school:"Cuerpo y Tiempo",title:"Neurociencias del Sue\xf1o",degree:"Licenciado/a en Neurociencias del Sue\xf1o",years:5,jornada:"Nocturna",cupos:28,arancel:621e4,image:"/images/laboratorio.jpg",alt:"Laboratorio de sue\xf1o: cama detr\xe1s del vidrio, amplificadores y una l\xe1mpara \xe1mbar",lead:"El reloj biol\xf3gico se mide. No se opina. Cinco a\xf1os de laboratorio, cl\xednica y escritura.",body:"Chile duerme mal y lo estudia poco. Aqu\xed el sue\xf1o es materia: EEG, cronobiolog\xeda, turno, altura, la noche laboral. El laboratorio est\xe1 en el predio y abre cuando el sujeto duerme. El seminario es de doce. No hay ‘wellness’: hay serie, protocolo y un informe que un hospital puede usar.",forWhom:"Quien viene de la biolog\xeda, de la medicina o de la ingenier\xeda, y no quiere elegir entre ellas. Quien acepta las vigilias del laboratorio.",plan:[{year:"1–2",items:"Fisiolog\xeda, estad\xedstica, neuroanatom\xeda, protocolo de laboratorio."},{year:"3–4",items:"Polisomnograf\xeda, cronobiolog\xeda, cl\xednica del sue\xf1o, seminario."},{year:"5",items:"Memoria: una serie propia, un protocolo, una defensa."}],weights:[{label:"NEM",value:"15%"},{label:"Ranking",value:"15%"},{label:"Comp. Lectora",value:"20%"},{label:"Comp. Matem\xe1tica 1",value:"25%"},{label:"Ciencias",value:"25%"}],faculty:"isidora-paredes",portfolio:!1,vigilia:!0,outcomes:["Laboratorios de sue\xf1o","Cl\xednica e investigaci\xf3n","Pol\xedtica de turnos y salud"]},{slug:"urbanismo",n:"05",school:"Ciudad y Signo",title:"Urbanismo",degree:"Urbanista",years:5,jornada:"Nocturna",cupos:28,arancel:574e4,image:"/images/terraza.jpg",alt:"Terraza h\xfameda del campus con un farol \xe1mbar y Santiago encendido al fondo",lead:"La ciudad de d\xeda es un plano. De noche es un organismo. Se ense\xf1a mir\xe1ndola encendida.",body:"Santiago se planifica a las once de la ma\xf1ana y se vive a las once de la noche. Aqu\xed el urbanismo parte de esa hora: el turno, el comercio 24h, el borde, la luz, el silencio desigual. Cinco a\xf1os de dibujo, dato, derecho urbano y terraza. El t\xedtulo es un informe que un municipio puede leer en un concejo.",forWhom:"Quien quiere el plano y la frase precisa. Quien no confunde ciudad con skyline ni noche con ‘seguridad’.",plan:[{year:"1–2",items:"Dibujo, historia urbana de Chile, SIG, escritura de informe."},{year:"3–4",items:"Taller de borde, de turno, de luz. Derecho y hacienda municipal."},{year:"5",items:"Memoria sobre una comuna nominada, no gen\xe9rica."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"25%"},{label:"Comp. Matem\xe1tica 1",value:"15%"},{label:"Historia y Cs. Sociales",value:"20%"}],faculty:"vicente-palma",portfolio:!0,vigilia:!1,outcomes:["Municipios y MINVU","Consultor\xeda de borde","Investigaci\xf3n de ciudad"]},{slug:"diseno",n:"06",school:"Ciudad y Signo",title:"Dise\xf1o",degree:"Dise\xf1ador/a",years:4,jornada:"Nocturna",cupos:28,arancel:548e4,image:"/images/taller.jpg",alt:"Taller de maquetas bajo una l\xe1mpara \xe1mbar: papel, l\xe1piz y un edificio de cart\xf3n",lead:"Objetos, signos y sistemas. Nada de creatividad como adjetivo vac\xedo.",body:"El dise\xf1o en NOCTUA parte del uso y de la luz. Tipograf\xeda, objeto, interfaz y espacio se ense\xf1an en el mismo taller: si no se puede hacer a mano, no se digitaliza. El portafolio de egreso es una pieza, no un PDF de mockups. El taller abre de noche porque la concentraci\xf3n pide esa hora.",forWhom:"Quien quiere oficio, no moodboard. Quien acepta que el primer a\xf1o se dibuja y se recorta antes de abrir un software.",plan:[{year:"1–2",items:"Dibujo, tipograf\xeda, material, color, historia de la forma."},{year:"3",items:"Taller de objeto, de edici\xf3n, de interfaz. Encargo real."},{year:"4",items:"T\xedtulo: una pieza producida, no ilustrada."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"30%"},{label:"Comp. Matem\xe1tica 1",value:"20%"},{label:"Historia y Cs. Sociales",value:"10%"}],faculty:"francisca-valdivia",portfolio:!0,vigilia:!1,outcomes:["Estudios de dise\xf1o","Edici\xf3n y tipograf\xeda","Producto e interfaz"]},{slug:"letras",n:"07",school:"Ciudad y Signo",title:"Literatura y Archivo",degree:"Licenciado/a en Literatura y Archivo",years:4,jornada:"Nocturna",cupos:24,arancel:476e4,image:"/images/biblioteca.jpg",alt:"Sala de lectura nocturna: mesas de roble, l\xe1mparas de bronce y ventanales al cielo oscuro",lead:"Leer en serio. Archivar en serio. El documento como oficio, no como contenido.",body:"Cuatro a\xf1os de lectura, filolog\xeda, paleograf\xeda y taller de archivo. La biblioteca de NOCTUA no es un living: es una sala de trabajo que cierra a las dos. Se egresa con un inventario hecho y un libro editado — no con un ensayo sobre ‘el futuro de la lectura’.",forWhom:"Quien lee m\xe1s de lo que publica. Quien quiere el oficio del original, de la caja y de la ficha.",plan:[{year:"1–2",items:"Literatura chilena y del Pac\xedfico, lat\xedn o griego, teor\xeda, escritura."},{year:"3",items:"Taller de archivo, edici\xf3n, traducci\xf3n. Encargo con un fondo."},{year:"4",items:"T\xedtulo: un inventario y un libro, de punta a punta."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"40%"},{label:"Comp. Matem\xe1tica 1",value:"10%"},{label:"Historia y Cs. Sociales",value:"10%"}],faculty:"amanda-soto",portfolio:!1,vigilia:!1,outcomes:["Archivos y bibliotecas","Edici\xf3n y traducci\xf3n","Docencia e investigaci\xf3n literaria"]},{slug:"gobierno",n:"08",school:"Ciudad y Signo",title:"Gobierno de la Ciudad",degree:"Cientista Pol\xedtico/a",years:4,jornada:"Nocturna",cupos:28,arancel:531e4,image:"/images/seminario.jpg",alt:"Mesa ovalada de seminario con Santiago encendido detr\xe1s del ventanal",lead:"Gobernar es una forma de mirar. Se ense\xf1a en seminario, no en auditorio.",body:"Instituciones chilenas, hacienda, turno y escritura p\xfablica. El seminario es de doce: se habla y se escribe, no se toma apunte de una diapositiva. El egreso es un informe que un municipio podr\xeda usar a las once de la noche — no un paper que nadie lee.",forWhom:"Quien quiere el Estado por dentro, no el comentario. Quien acepta leer ley, presupuesto y parte policial.",plan:[{year:"1–2",items:"Historia institucional de Chile, teor\xeda, econom\xeda, escritura p\xfablica."},{year:"3",items:"Seminario de hacienda, de turno, de ciudad. Pasant\xeda municipal."},{year:"4",items:"Memoria: un problema nominado, un informe, una defensa."}],weights:[{label:"NEM",value:"20%"},{label:"Ranking",value:"20%"},{label:"Comp. Lectora",value:"30%"},{label:"Comp. Matem\xe1tica 1",value:"15%"},{label:"Historia y Cs. Sociales",value:"15%"}],faculty:"vicente-palma",portfolio:!1,vigilia:!1,outcomes:["Municipios y ministerios","Think tanks y archivo","Asesor\xeda de ciudad"]}],n=[{q:"\xbfNOCTUA es universidad o instituto?",a:"Instituto universitario de sede \xfanica. Ocho carreras de pregrado y tres mag\xedster. No abrimos una novena para parecer m\xe1s grandes. El t\xedtulo profesional lo otorga la Fundaci\xf3n Instituto NOCTUA."},{q:"\xbfEs vespertino? \xbfHay jornada diurna u online?",a:"No es vespertino. Es jornada nocturna: clases de 17:30 a 01:00, lunes a viernes. No hay diurno, no hay online, no hay ‘flexible’. El oficio pide esa hora. Si no cabe en ella, no es este instituto."},{q:"\xbfC\xf3mo se entra? \xbfHay que dar la PAES?",a:"S\xed. Admisi\xf3n 2027 usa PAES 2026, NEM y ranking. Cine, dise\xf1o y urbanismo piden adem\xe1s un portafolio de diez l\xe1minas. Astronom\xeda, cine y neurociencias incluyen una vigilia de observaci\xf3n en el campus. Todas las carreras tienen entrevista de 25 minutos. Las ponderaciones est\xe1n publicadas en cada carrera."},{q:"\xbfQu\xe9 es la vigilia?",a:"Una noche en el recinto, de 20:00 a 00:30, antes de la carta de admisi\xf3n. Se observa, se anota, se habla. No es un test psicol\xf3gico ni un reality. Es la prueba de que la hora te sirve. Astronom\xeda, cine y neurociencias la piden; el resto, no."},{q:"\xbfCu\xe1nto cuesta? \xbfHay gratuidad o CAE?",a:"El arancel anual va de $4.760.000 (Letras) a $6.320.000 (Datos). Matr\xedcula $340.000. Publicamos la cifra, no un ‘desde’. Informamos las v\xedas de financiamiento vigentes en Chile; no prometemos beneficios que no administramos. La Beca Vigilia y la Beca Recoleta s\xed son nuestras."},{q:"\xbfPuedo visitar el campus?",a:"S\xed. S\xe1bados de marzo a enero, 10:00 a 14:00, con inscripci\xf3n previa. El recorrido dura una hora: terraza, biblioteca, un seminario, el laboratorio o la sala oscura. Lo gu\xeda un estudiante, no un vendedor. De noche, solo con postulaci\xf3n en curso."}]},5985:(e,a,o)=>{o.r(a),o.d(a,{Reveal:()=>r});var i=o(5155),n=o(2115),l=o(1442);function r({children:e,className:a,delay:o=0}){let s=(0,n.useRef)(null);return(0,n.useEffect)(()=>{let e=s.current;if(!e)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return void e.classList.add("is-visible");let a=new IntersectionObserver(([o])=>{o.isIntersecting&&(e.classList.add("is-visible"),a.disconnect())},{threshold:.16,rootMargin:"0px 0px -8% 0px"});return a.observe(e),()=>a.disconnect()},[]),(0,i.jsx)("div",{ref:s,className:(0,l.cn)("reveal",a),style:{transitionDelay:`${o}ms`},children:e})}}}]);